inline const Profile* Lookup(uint32_t code) { for (const auto& p:kProfiles) if(p.code==code)return &p; return nullptr; }
inline bool Observed(uint32_t code) {const auto* p=Lookup(code);return p&&p->observed;}
inline uint32_t ObservedStencilMask(uint32_t code,bool gl2) {const auto* p=Lookup(code);return p&&p->observed?p->stencilMasks[gl2?1:0]:0;}
inline float ObservedLodBias(uint32_t code) {return Observed(code)?2.0f:0.0f;}
inline const Context* ForContext(uint32_t code, bool gl2) { const auto* p=Lookup(code); return p?p->contexts[gl2?1:0]:nullptr; }
inline const Parameter* Find(uint32_t code,bool gl2,uint32_t pname) {const auto* c=ForContext(code,gl2);if(c)for(size_t i=0;i<c->parameterCount;i++)if(c->parameters[i].pname==pname)return &c->parameters[i];return nullptr;}
inline uint32_t Cap(uint32_t code,bool gl2,uint32_t pname) {const auto* p=Find(code,gl2,pname);return p?uint32_t(p->lo):0;}
inline bool HasExtension(const Context& c,std::string_view name) {for(size_t i=0;i<c.extensionCount;i++)if(name==c.extensions[i])return true;return false;}
